window.products.push({"id":1054516,"name":"Fred FISH Party Picks, Set of 24","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/81pvw7CbCyL._AC_SL1500_.jpg","description":"Use these Fred and Friends FISH STIX Party Picks at your next party or gathering. This set includes 24 picks. The party picks are made of polypropylene. Use the picks to serve olives, cheese cubes, strawberries, or other small or bite-sized foods. The picks are reusable, just wash and dry for your next round of appetizers. The picks are packaged in a sardine can styled box.","images":["https://m.media-amazon.com/images/I/81pvw7CbCyL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Fred & Friends","source_asin":"B004T6H7JI","category_path":"Home & Kitchen"},"sku":"BM-1054516","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B004T6H7JI","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B004T6H7JI","price_pending":true,"merchant_ready":false});
